!function(){"use strict";app.factory("facturaService",(function($injector){let url="Factura/",mainService=$injector.get("mainService"),formSvc=$injector.get("formulario"),service={getAll:function(query){return mainService.getData("get",url+"Get?json="+JSON.stringify(query),null,!0).then(response=>{if("0"===response.code)throw response;if("1"===response.code){let facturas;return(JSON.parse(response.payload)||[]).map(item=>({idFactura:item.idFactura,idTipoDocumento:item.idTipoDocumento,idTiempoCredito:item.idTiempoCredito,idCliente:item.idCliente,codEstab:item.codEstab,fechaEmision:item.fechaEmision,fechaVencimiento:item.fechaVencimiento,total:item.total,nroFactura:item.nroFactura,nombreFiscal:item.nombreFiscal,correos:item.correos,identificacionComprador:item.identificacionComprador,estadoFinanciero:item.estadoFinanciero,estadoSri:item.estadoSri,claveAcceso:item.claveAcceso,codDoc:item.codDoc,tipo:item.tipo,abono:item.abono,saldo:item.saldo,posfechado:item.posfechado,style:item.style,usuario:item.usuario,nroNotaCredito:item.nroNotaCredito,nroGuiaRemision:item.nroGuiaRemision,nroRetencion:item.nroRetencion,nroIdentificacion:item.nroIdentificacion,anulada:item.anulada}))}})},save:function(data){return mainService.getData("post",url+"Insert",data,!0).then(response=>{if("0"===response.code)return response;if("1"===response.code){let dataRepository=JSON.parse(response.payload)[0],dataResponse;return{dataResponse:{...dataRepository,nroDocumento:dataRepository.estab+dataRepository.ptoEmi+dataRepository.secuencial,esContado:dataRepository.gestion},code:"1"}}})},update:function(id,data){return mainService.getData("put",url+"Update/"+id,data,!0).then(response=>"0"===response.code?response:"1"===response.code?response:void 0)},delete:function(id){return mainService.getData("delete",url+"Delete/"+id,null,!0).then(response=>response)},queryMapper:function({data:data,cliente:cliente,detalles:detalles,infoAdicionalDocumento:infoAdicionalDocumento,historyDatosAdicionales:historyDatosAdicionales}){let factura=Object.assign({},data);return factura.idCliente=cliente.idCliente,factura.fechaEmision=formSvc.formatDateTimeZone(data.fechaEmision),factura.fechaVencimiento=formSvc.formatDateTimeZone(data.fechaVencimiento),{factura:JSON.stringify(factura),detalle:JSON.stringify(service.detalleMapperTo(detalles)),adicional:JSON.stringify(infoAdicionalDocumento||[]),infoAdicionalArticulo:JSON.stringify(historyDatosAdicionales)}},detalleMapperTo:function(detalles){let tempDetails=[],orderIndex=1;for(let item of detalles)tempDetails.push({orderIndex:orderIndex++,idFacturaDetalle:item.idFacturaDetalle||0,idArticulo:item.idArticulo,idTarifa:item.idTarifa,idBodega:item.idBodega,idMedida:item.idMedida,idPresentacion:item.idPresentacion||0,idTipoIva:item.idTipoIva,tarifa:item.tarifa,codigoPorcentaje:item.codigoPorcentaje,ice:item.ice,descripcion:item.descripcion,cantidad:item.cantidad,precioCostoNeto:item.precioCostoNeto,precioUnitario:item.precioUnitario,precioVenta:item.precioUnitario,precioConIva:item.precioConIva,valorDescuento:item.valorDescuento,precioTotalSinImpuesto:item.precioTotalSinImpuesto||0,porcentajeDescuento:item.porcentajeDescuento,total:item.total,nota:item.nota});return tempDetails}};return service}))}(window.angular);